import { test, expect } from '@playwright/test';

test.describe('Inline Table Row Editing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Wait for table to load
    await page.getByRole('table').waitFor({ state: 'visible' });
  });

  test('should enable inline editing when clicking on a table cell', async ({ page }) => {
    // Get the first row in the table
    const firstRow = page.getByRole('row').nth(1);

    // Click on the name cell to enable inline editing
    const nameCell = firstRow.getByRole('cell').nth(1);
    await nameCell.click();

    // Verify that an input field appears for editing
    const editInput = nameCell.getByRole('textbox');
    await expect(editInput).toBeVisible();

    // Verify the input contains the original value
    const originalValue = await nameCell.textContent();
    await expect(editInput).toHaveValue(originalValue?.trim() || '');
  });

  test('should update table cell value when editing inline and pressing Enter', async ({ page }) => {
    const firstRow = page.getByRole('row').nth(1);
    const nameCell = firstRow.getByRole('cell').nth(1);

    // Click to enable editing
    await nameCell.click();

    // Get the input field and clear it
    const editInput = nameCell.getByRole('textbox');
    await editInput.clear();

    // Type new value
    const newValue = 'Updated Name';
    await editInput.fill(newValue);

    // Press Enter to save
    await editInput.press('Enter');

    // Verify the cell is no longer in edit mode
    await expect(editInput).not.toBeVisible();

    // Verify the new value is displayed in the cell
    await expect(nameCell).toContainText(newValue);
  });

  test('should cancel inline editing when pressing Escape', async ({ page }) => {
    const firstRow = page.getByRole('row').nth(1);
    const emailCell = firstRow.getByRole('cell').nth(2);

    // Get original value before editing
    const originalValue = await emailCell.textContent();

    // Click to enable editing
    await emailCell.click();

    // Get the input field and modify it
    const editInput = emailCell.getByRole('textbox');
    await editInput.clear();
    await editInput.fill('newemail@example.com');

    // Press Escape to cancel
    await editInput.press('Escape');

    // Verify the cell is no longer in edit mode
    await expect(editInput).not.toBeVisible();

    // Verify the original value is still displayed
    await expect(emailCell).toContainText(originalValue?.trim() || '');
  });

  test('should allow editing multiple cells in sequence without modal', async ({ page }) => {
    const firstRow = page.getByRole('row').nth(1);

    // Edit first cell (name)
    const nameCell = firstRow.getByRole('cell').nth(1);
    await nameCell.click();
    const nameInput = nameCell.getByRole('textbox');
    await nameInput.clear();
    await nameInput.fill('John Doe');
    await nameInput.press('Enter');

    // Verify first cell is updated
    await expect(nameCell).toContainText('John Doe');

    // Edit second cell (email)
    const emailCell = firstRow.getByRole('cell').nth(2);
    await emailCell.click();
    const emailInput = emailCell.getByRole('textbox');
    await emailInput.clear();
    await emailInput.fill('john@example.com');
    await emailInput.press('Enter');

    // Verify second cell is updated
    await expect(emailCell).toContainText('john@example.com');

    // Verify no modal is open
    const modal = page.getByRole('dialog');
    await expect(modal).not.toBeVisible();
  });

  test('should show validation error for invalid input during inline editing', async ({ page }) => {
    const firstRow = page.getByRole('row').nth(1);
    const emailCell = firstRow.getByRole('cell').nth(2);

    // Click to enable editing
    await emailCell.click();

    // Enter invalid email
    const editInput = emailCell.getByRole('textbox');
    await editInput.clear();
    await editInput.fill('invalid-email');

    // Try to save with invalid value
    await editInput.press('Enter');

    // Verify error message appears
    const errorMessage = page.getByText(/invalid email/i);
    await expect(errorMessage).toBeVisible();

    // Verify the cell is still in edit mode
    await expect(editInput).toBeVisible();
  });

  test('should blur and save when clicking outside the edited cell', async ({ page }) => {
    const firstRow = page.getByRole('row').nth(1);
    const nameCell = firstRow.getByRole('cell').nth(1);

    // Click to enable editing
    await nameCell.click();

    // Modify the value
    const editInput = nameCell.getByRole('textbox');
    await editInput.clear();
    await editInput.fill('New Name Value');

    // Click on another cell to blur
    const secondRow = page.getByRole('row').nth(2);
    const otherCell = secondRow.getByRole('cell').nth(1);
    await otherCell.click();

    // Verify the first cell is no longer in edit mode
    await expect(nameCell.getByRole('textbox')).not.toBeVisible();

    // Verify the new value is saved
    await expect(nameCell).toContainText('New Name Value');
  });
});
